cssOverrides:
/* Navagarden – site-specific overrides */

:root {
  --color-brand-primary: var(--color-brand-primary);
  --color-brand-secondary: var(--color-brand-secondary);
  --color-brand-accent: var(--color-brand-accent);
  --color-brand-on-primary: var(--color-brand-on-primary);
  --color-surface-background: var(--color-surface-background);
  --color-surface-foreground: var(--color-surface-foreground);
  --color-surface-muted: var(--color-surface-muted);
  --color-surface-card: var(--color-surface-card);
  --color-surface-card-border: var(--color-surface-card-border);
  --font-heading: var(--font-heading);
  --font-sans: var(--font-sans);
  --nav-height: 72px;
  --section-padding-y: clamp(4rem, 6vw, 6rem);
  --container-max-width: 80rem;
  --radius-rounded: 0.375rem;
  --radius-xl: 0.75rem;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-surface-background);
  color: var(--color-surface-foreground);
  font-weight: 300;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--color-brand-secondary);
}

a {
  color: var(--color-brand-primary);
}

a:hover {
  color: var(--color-brand-primary-hover);
}

.btn-primary {
  background-color: var(--color-brand-primary);
  color: var(--color-brand-on-primary);
  border-radius: var(--radius-rounded);
  font-family: var(--font-sans);
  font-weight: 500;
}

.btn-primary:hover {
  background-color: var(--color-brand-primary-hover);
}

.card {
  background-color: var(--color-surface-card);
  border: 1px solid var(--color-surface-card-border);
  border-radius: var(--radius-xl);
}

.site-nav {
  background-color: var(--color-surface-card);
  height: var(--nav-height);
}

.site-nav a {
  color: var(--color-brand-secondary);
  font-family: var(--font-sans);
  font-weight: 500;
}

.site-footer {
  background-color: var(--color-brand-secondary);
  color: var(--color-surface-card);
}

.site-footer a {
  color: var(--color-brand-primary);
}

.hero-split {
  background-color: var(--color-surface-card);
}

.hero-split__text {
  color: var(--color-brand-secondary);
}

.section-muted {
  background-color: var(--color-surface-muted);
}

.text-accent {
  color: var(--color-brand-primary);
}

.overlay-dark {
  background-color: var(--color-overlay-dark);
}

.overlay-primary {
  background-color: var(--color-overlay-primary);
}
